    ('495bde51-8e9c-47de-9b7c-ecb5ff8cb9f2', '0f58af04-1b8f-4d51-8bb4-f32b361d0be9', 'Recruitment & Talent Acquisition (High-Volume Hiring)', 'Pearl Lemon Group', 'https://www.linkedin.com/company/37396409/', 'London Area, United Kingdom · Remote', '2026-01-01', '2026-06-01', E'• Screened and evaluated 200+ candidates across multiple roles.\n\n• Shortlisted candidates based on role requirements and experience.\n\n• Managed candidate communication and follow-ups throughout the hiring process.\n\n• Reviewed Loom/video introductions to assess candidate suitability.\n\n• Coordinated with international candidates and global team members.\n\n• Maintained and updated the recruitment pipeline.\n\n• Supported onboarding of selected candidates.\n\n• Created and posted job descriptions across multiple platforms, including Wellfound, Internshala, Hubstaff Talent, OnlineJobs.ph, and Indeed.', 2),
    ('d8c71aa9-cd96-4d06-8eb0-352bec3132a0', '0f58af04-1b8f-4d51-8bb4-f32b361d0be9', 'Senior Accounts Payable Accountant', 'Tanmeyah', 'https://www.linkedin.com/company/1043448/', NULL, '2017-02-01', '2022-05-01', E'• Prepared monthly accruals and necessary journal entries.\n\n• Issued invoices and followed up on payments.\n\n• Charged expenses to accounts and cost centers by analyzing invoice and expense reports.\n\n• Prepared, maintained, examined, and analyzed accounting records.\n\n• Reviewed journal entries and reconciled the general ledger.\n\n• Prepared withholding tax each quarter.\n\n• Maintained files and documentation thoroughly and accurately in accordance with company policy and accepted accounting practices.\n\n• Reviewed supplier invoices for accuracy and managed payments on time according to policy.\n\n• Supported external audit requirements.', 3)
